 };
 return <svg width={size} height={size} viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.65\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">{paths[name]}</svg>;
}
const nf = new Intl.NumberFormat('ru-RU');
const base = [1440,1610,1530,1880,1760,1690,1970,2030,1780,1860,2130,2020,2310,2180,2070,2410,2590,2360,2500,2240,2430,2710,2560,2830,2660,2910,2790,3150,2990,3240];
function smooth(points:number[][]) {return points.map(([x,y], i) => i === 0 ? "'`M ${x} ${y}` : `C ${(points[i-1][0]+x)/2} ${points[i-1][1]}, ${(points[i-1][0]+x)/2} ${y}, ${x} ${y}`).join('"' ');}
export function App({theme, onTheme}: {theme: string; onTheme: (theme: 'light'|'dark'|'system')=>void}) {
