 const total=data.reduce((s,d)=>s+d.current,0), prevTotal=data.reduce((s,d)=>s+d.previous,0);
 const max=Math.ceil(Math.max(...data.map(d=>Math.max(d.current,d.previous)))/1000)*1000;
 const points=data.map((d,i)=>[64+i/(data.length-1)*936,292-d.current/max*254]);
 const previous=data.map((d,i)=>[64+i/(data.length-1)*936,292-d.previous/max*254]);
 const dateLabel=(i:number)=> period===90?new Date(2026,7,3+i*3).toLocaleDateString('ru-RU',{day:'numeric',month:'short'}):"'`${31-period+i} окт.`;
 const range=period===90?'"'3 авг. — 31 окт. 2026':"'`${31-period} — 30 октября 2026`;
 function download(){const csv='"'\\uFEFFДата;Текущий период;Предыдущий период\\n'+data.map((d,i)=>"'`${dateLabel(i)};${d.current};${d.previous}`).join('"'\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download="'`pulse-${metric}-${period}days.csv`;a.click();URL.revokeObjectURL(url);}
 function navigate(id:string){setActive(id);if(id==='"'data')setModal('data');else document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});}
 return <div className=\"app\" data-theme={actualTheme}>
  <aside className=\"sidebar\">
   <a className=\"brand\" href=\"#\" onClick={()=>navigate('overview')}><span className=\"brand-mark\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M3 13h4l3-7 4 13 3-8h4\" stroke=\"currentColor\" strokeWidth=\"2.3\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg></span>pulse<span className=\"brand-dot\">.</span></a>
   <div className=\"workspace\"><span className=\"workspace-icon\">S</span><div><strong>Studio workspace</strong><small>Личное пространство</small></div><span className=\"workspace-status\" title=\"Пространство активно\"/></div>
   <div className=\"nav-caption\">РАБОЧЕЕ ПРОСТРАНСТВО</div>
   <nav>{[['overview','grid','Обзор'],['dynamics','chart','Динамика'],['data','layers','Данные']].map(([id,icon,label])=><button className={"'`nav-item ${active===id?'"'selected':''}"'`} key={id} onClick={()=>navigate(id)}><Icon name={icon as IconName}/>{label}{active===id&&<span className="nav-dot"/>}</button>)}</nav>
   <div className="sidebar-bottom"><div className="theme-label">Оформление <span>{actualTheme==='"'light'?'Светлая тема':'Тёмная тема'}</span></div><div className=\"theme-switch\">{(['light','dark','system'] as const).map((t,i)=><button key={t} className={theme===t?'chosen':''} onClick={()=>onTheme(t)} aria-label={['Светлая тема','Тёмная тема','Системная тема'][i]} title={['Светлая тема','Тёмная тема','Системная тема'][i]}><Icon name={(['sun','moon','monitor'] as const)[i]}/></button>)}</div><button className=\"help-button\" onClick={()=>setModal('help')}><Icon name=\"help\"/>Помощь и поддержка<Icon name=\"external\" size={15}/></button><div className=\"profile\"><div className=\"avatar\">АК</div><div><strong>Александр К.</strong><small>Личный аккаунт</small></div><span className=\"profile-dot\"/></div></div>
  </aside>
  <div className=\"main-wrap\"><header className=\"topbar\"><div className=\"breadcrumb\">Рабочее пространство <span>/</span><strong>Обзор</strong></div><span className=\"live\"><i/>Демо-данные</span></header>
   <main id=\"overview\"><div className=\"page-heading\"><div><div className=\"eyebrow\">ВАША АНАЛИТИКА, БЕЗ ЛИШНЕГО</div><h1>Всё начинается с динамики<span>.</span></h1><p>Наблюдайте за показателями и находите новые точки роста.</p></div><button className=\"button export\" onClick={download}><Icon name=\"download\" size={17}/>Экспорт данных</button></div>
   <div className=\"toolbar\"><div className=\"tabs\">{[7,30,90].map(p=><button key={p} className={period===p?'active':''} onClick={()=>{setPeriod(p);setHover(null);}}>{p} дней</button>)}</div><div className=\"date\"><Icon name=\"calendar\" size={17}/>{range}</div></div>
   <section className=\"stats\" aria-label=\"Основные показатели\"><Stat title=\"Посетители\" value={nf.format(metric==='visitors'?total:Math.round(total/2.48))} change=\"24,8%\" icon=\"users\" active={metric==='visitors'} onClick={()=>setMetric('visitors')}/><Stat title=\"Просмотры\" value={nf.format(metric==='views'?total:Math.round(total*2.48))} change=\"18,6%\" icon=\"eye\" active={metric==='views'} onClick={()=>setMetric('views')}/><div className=\"stat\"><div className=\"stat-title\">Среднее время <Icon name=\"clock\" size={18}/></div><div className=\"stat-value\">3 <span>мин</span> 42 <span>с</span></div><div className=\"stat-bottom\"><span className=\"change\">↗ 12,3%</span><span>к предыдущему периоду</span></div></div></section>
   <section className=\"chart-card\" id=\"dynamics\"><div className=\"chart-heading\"><div><h2>Динамика посещаемости</h2><p>Как меняется активность вашей аудитории</p></div><div className=\"select-wrap\"><select value={metric} onChange={e=>setMetric(e.target.value)} aria-label=\"Показатель графика\"><option value=\"visitors\">Посетители</option><option value=\"views\">Просмотры</option></select><Icon name=\"chevron\" size={16}/></div></div>
   <div className=\"chart-meta\"><div className=\"legend\">{['Текущий период','Предыдущий период'].map((l,i)=><button key={l} onClick={()=>setVisible(v=>v.map((x,j)=>i===j?"'!x:x))} aria-pressed={visible[i]} className={!visible[i]?'"'muted-series':''}><span className={"'`legend-line line-${i}`}/>{l}</button>)}</div><span className="unit">{metric==='"'visitors'?'Посетители':'Просмотры'}, чел.</span></div>
   <div className=\"chart-container\" onMouseLeave={()=>setHover(null)}><svg className=\"chart\" viewBox=\"0 0 1030 344\" role=\"img\" aria-label={"'`Линейный график: ${metric==='"'visitors'?'посетители':'просмотры'} за "'${period} дней`}>
    <defs><linearGradient id={gradient} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--green)" stopOpacity=".15"/><stop offset="100%" stopColor="var(--green)" stopOpacity="0"/></linearGradient></defs>
    {[0,1,2,3,4].map(i=><g key={i}><line x1="64" y1={38+i*63.5} x2="1000" y2={38+i*63.5} className="gridline"/><text x="44" y={42+i*63.5} textAnchor="end" className="axis-label">{nf.format(max-i*max/4)}</text></g>)}
    {visible[0]&&<path d={`${smooth(points)} L 1000 292 L 64 292 Z`} fill={`url(#${gradient})`}/>}{visible[1]&&<path d={smooth(previous)} fill="none" className="previous-line" strokeWidth="2.3" strokeDasharray="5 6"/>}{visible[0]&&<path d={smooth(points)} fill="none" stroke="var(--green)" strokeWidth="3" strokeLinecap="round"/>}
    {data.map((d,i)=> (i===0||i===data.length-1||i%Math.ceil((data.length-1)/6)===0)&&<text key={i} x={points[i][0]} y="326" className="axis-label" textAnchor="middle">{dateLabel(i)}</text>)}
    {hover!==null&&<g><line x1={points[hover][0]} x2={points[hover][0]} y1="28" y2="292" stroke="var(--muted)" strokeDasharray="4 4"/>{visible[0]&&<circle cx={points[hover][0]} cy={points[hover][1]} r="5" fill="var(--green)" stroke="var(--card)" strokeWidth="3"/>}{visible[1]&&<circle cx={previous[hover][0]} cy={previous[hover][1]} r="4" fill="var(--previous)" stroke="var(--card)" strokeWidth="2"/>}</g>}
    {data.map((d,i)=><rect key={i} x={points[i][0]-468/(data.length-1)} y="20" width={936/(data.length-1)} height="280" fill="transparent" onMouseEnter={()=>setHover(i)} onClick={()=>setHover(i)}/>)}
   </svg>{hover!==null&&<div className="tooltip" style={{left:`${Math.min(76,Math.max(5,points[hover][0]/1030*100-9))}%`}}><strong>{dateLabel(hover)} 2026</strong>{visible[0]&&<div><span><i/>Текущий</span><b>{nf.format(data[hover].current)}</b></div>}{visible[1]&&<div><span><i className="prev-dot"/>Предыдущий</span><b>{nf.format(data[hover].previous)}</b></div>}</div>}</div>
   <div className="chart-footer"><span><span className="small-dot"/>Данные по дням</span><button onClick={()=>setModal('"'data')}>Посмотреть данные<Icon name=\"arrow\" size={15}/></button></div></section>
   <section className=\"insight\"><span className=\"insight-icon\"><Icon name=\"chart\" size={22}/></span><div><strong>Хороший темп роста</strong><p>За выбранный период {metric==='visitors'?'посещаемость выросла':'просмотры выросли'} на <b>{((total/prevTotal-1)*100).toLocaleString('ru-RU',{maximumFractionDigits:1})}%</b>. Продолжайте в том же духе.</p></div><span className=\"insight-pill\">Есть прогресс<Icon name=\"arrow\" size={14}/></span></section>
   <footer className=\"page-footer\"><span>Меньше шума. Больше понимания.</span><span><span className=\"small-dot\"/>Все показатели в одном месте</span></footer>
  </main></div>
  {modal&&<div className=\"modal-overlay\" onClick={()=>setModal(null)}><section role=\"dialog\" aria-modal=\"true\" aria-label={modal==='data'?'Данные графика':'Помощь'} className=\"modal\" onClick={e=>e.stopPropagation()} onKeyDown={e=>{if(e.key==='Escape')setModal(null)}}><button className=\"close-button\" aria-label=\"Закрыть\" autoFocus onClick={()=>setModal(null)}><Icon name=\"close\"/></button><h2>{modal==='data'?'Данные графика':'Всё о вашей аналитике'}</h2>{modal==='data'?<><p>{range} · {metric==='visitors'?'Посетители':'Просмотры'} · Демо-данные</p><div className=\"table-scroll\"><table><thead><tr><th>Дата</th><th>Текущий период</th><th>Предыдущий</th></tr></thead><tbody>{data.map((d,i)=><tr key={i}><td>{dateLabel(i)}</td><td>{nf.format(d.current)}</td><td>{nf.format(d.previous)}</td></tr>)}</tbody></table></div><button className=\"button\" onClick={download}><Icon name=\"download\" size={17}/>Скачать CSV</button></>:<div className=\"help-copy\"><p>Выберите период 7, 30 или 90 дней, чтобы увидеть динамику. Переключайте посетителей и просмотры в меню над графиком.</p><p>Наведите указатель на линию или коснитесь графика для просмотра значений. Нажмите на легенду, чтобы скрыть или показать ряд.</p><p>Оформление можно выбрать внизу боковой панели. Системная тема автоматически следует настройкам устройства.</p><p>На экране представлены демонстрационные данные. Кнопка «Экспорт данных» сохраняет выбранный период в CSV.</p></div>}</section></div>}
 </div>;
}
